package com.example.redpacket;
import android.accessibilityservice.AccessibilityService;import android.os.*;import android.view.accessibility.*;import java.util.*;
public class PacketAccessibility extends AccessibilityService {
 private final Handler handler=new Handler(Looper.getMainLooper());private final Set<String> seen=new LinkedHashSet<>();private long lastAction=0;private boolean pending=false;
 @Override public void onAccessibilityEvent(AccessibilityEvent event){if(event==null||event.getPackageName()==null||!"com.tencent.mm".contentEquals(event.getPackageName()))return;if(!getSharedPreferences("MainActivity",0).getBoolean("enabled",false)||pending||System.currentTimeMillis()-lastAction<900)return;AccessibilityNodeInfo root=getRootInActiveWindow();if(root==null)return;AccessibilityNodeInfo open=findExact(root,"开",0);if(open!=null&&contains(root,"红包",0)){schedule(open);return;}AccessibilityNodeInfo packet=findPacket(root,0);if(packet!=null){android.graphics.Rect r=new android.graphics.Rect();packet.getBoundsInScreen(r);String key=r.flattenToString()+":"+String.valueOf(packet.getText())+":"+String.valueOf(packet.getContentDescription());if(!seen.contains(key)){if(seen.size()>80)seen.clear();seen.add(key);schedule(packet);}}}
 private void schedule(AccessibilityNodeInfo node){pending=true;int delay=getSharedPreferences("MainActivity",0).getInt("delay",300);handler.postDelayed(()->{try{if(getRootInActiveWindow()!=null&&clickParent(node))lastAction=System.currentTimeMillis();}catch(Exception ignored){}finally{pending=false;}},delay);}
 private boolean clickParent(AccessibilityNodeInfo n){for(int i=0;n!=null&&i<8;i++,n=n.getParent())if(n.isClickable())return n.performAction(AccessibilityNodeInfo.ACTION_CLICK);return false;}
 private AccessibilityNodeInfo findPacket(AccessibilityNodeInfo n,int depth){if(n==null||depth>35)return null;String s=String.valueOf(n.getText())+" "+String.valueOf(n.getContentDescription());if((s.contains("微信红包")||s.contains("领取红包"))&&!s.contains("已领取")&&!s.contains("已过期"))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo x=findPacket(n.getChild(i),depth+1);if(x!=null)return x;}return null;}
 private AccessibilityNodeInfo findExact(AccessibilityNodeInfo n,String word,int d){if(n==null||d>35)return null;if(word.equals(String.valueOf(n.getText()))||word.equals(String.valueOf(n.getContentDescription())))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo x=findExact(n.getChild(i),word,d+1);if(x!=null)return x;}return null;}
 private boolean contains(AccessibilityNodeInfo n,String word,int d){if(n==null||d>35)return false;if(String.valueOf(n.getText()).contains(word)||String.valueOf(n.getContentDescription()).contains(word))return true;for(int i=0;i<n.getChildCount();i++)if(contains(n.getChild(i),word,d+1))return true;return false;}
 @Override public void onInterrupt(){}
}